#include "spng.h"

#include <limits.h>
#include <string.h>
#include <math.h>

#include <zlib.h>

#define SPNG_CHUNK_IHDR (1U)
#define SPNG_CHUNK_PLTE (1U << 1)
#define SPNG_CHUNK_CHRM (1U << 2)
#define SPNG_CHUNK_ICCP (1U << 3)
#define SPNG_CHUNK_GAMA (1U << 4)
#define SPNG_CHUNK_SBIT (1U << 5)
#define SPNG_CHUNK_SRGB (1U << 6)
#define SPNG_CHUNK_TEXT (1U << 7)
#define SPNG_CHUNK_BKGD (1U << 8)
#define SPNG_CHUNK_HIST (1U << 9)
#define SPNG_CHUNK_TRNS (1U << 10)
#define SPNG_CHUNK_PHYS (1U << 11)
#define SPNG_CHUNK_SPLT (1U << 12)
#define SPNG_CHUNK_TIME (1U << 13)
#define SPNG_CHUNK_OFFS (1U << 14)
#define SPNG_CHUNK_EXIF (1U << 15)

#define SPNG_READ_SIZE 8192

#ifndef SPNG_DISABLE_OPT

    #if defined(__i386__) || defined(__x86_64__) || defined(_M_IX86) || defined(_M_X64)
        #define SPNG_X86
    #elif defined(__aarch64__) || defined(_M_ARM64) || defined(__ARM_NEON)
        /* #define SPNG_ARM */ /* buffer overflow for rgb8 images */
        #define SPNG_DISABLE_OPT
    #else
        #warning "disabling optimizations for unknown platform"
        #define SPNG_DISABLE_OPT
    #endif

    #ifndef SPNG_DISABLE_OPT
        static void defilter_sub3(size_t rowbytes, unsigned char *row);
        static void defilter_sub4(size_t rowbytes, unsigned char *row);
        static void defilter_avg3(size_t rowbytes, unsigned char *row, const unsigned char *prev);
        static void defilter_avg4(size_t rowbytes, unsigned char *row, const unsigned char *prev);
        static void defilter_paeth3(size_t rowbytes, unsigned char *row, const unsigned char *prev);
        static void defilter_paeth4(size_t rowbytes, unsigned char *row, const unsigned char *prev);
    #endif
#endif

#define SPNG_FILTER_TYPE_NONE 0
#define SPNG_FILTER_TYPE_SUB 1
#define SPNG_FILTER_TYPE_UP 2
#define SPNG_FILTER_TYPE_AVERAGE 3
#define SPNG_FILTER_TYPE_PAETH 4

#define SPNG_STR(x) _SPNG_STR(x)
#define _SPNG_STR(x) #x

#define SPNG_VERSION_STRING SPNG_STR(SPNG_VERSION_MAJOR) "." \
                            SPNG_STR(SPNG_VERSION_MINOR) "." \
                            SPNG_STR(SPNG_VERSION_PATCH)

#define SPNG_GET_CHUNK_BOILERPLATE(chunk) \
    if(ctx == NULL || chunk == NULL) return 1; \
    int ret = get_ancillary(ctx); \
    if(ret) return ret;

#define SPNG_SET_CHUNK_BOILERPLATE(chunk) \
    if(ctx == NULL || chunk == NULL) return 1; \
    int ret = get_ancillary2(ctx); \
    if(ret) return ret;


struct spng_ctx
{
    size_t data_size;
    size_t bytes_read;
    unsigned char *data;

    /* User-defined pointers for streaming */
    spng_read_fn *read_fn;
    void *read_user_ptr;

    /* Used for buffer reads */
    unsigned char *png_buf; /* base pointer for the buffer */
    size_t bytes_left;
    size_t last_read_size;

    /* These are updated by read_header()/read_chunk_bytes() */
    struct spng_chunk current_chunk;
    uint32_t cur_chunk_bytes_left;
    uint32_t cur_actual_crc;

    struct spng_alloc alloc;

    unsigned valid_state: 1;
    unsigned streaming: 1;

    unsigned encode_only: 1;

/* input file contains this chunk */
    unsigned file_ihdr: 1;
    unsigned file_plte: 1;
    unsigned file_chrm: 1;
    unsigned file_iccp: 1;
    unsigned file_gama: 1;
    unsigned file_sbit: 1;
    unsigned file_srgb: 1;
    unsigned file_text: 1;
    unsigned file_bkgd: 1;
    unsigned file_hist: 1;
    unsigned file_trns: 1;
    unsigned file_phys: 1;
    unsigned file_splt: 1;
    unsigned file_time: 1;
    unsigned file_offs: 1;
    unsigned file_exif: 1;

/* chunk was stored with spng_set_*() */
